def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    alive_opponents = []
    for opp in opponents_status.values():
        if opp.get('alive'):
            alive_opponents.append(opp)

    if budget <= 0:
        return 0.0

    if not alive_opponents:
        return float(min(budget, 20.0 if hp > 3 else 45.0))

    prev_bids = []
    urgent_opp_count = 0
    rich_opp_count = 0
    for opp in alive_opponents:
        if opp.get('budget', 0) >= 120:
            rich_opp_count += 1
        if opp.get('hp', 0) <= 3 or opp.get('no_water_days', 0) >= 1:
            urgent_opp_count += 1
        prev = opp.get('previous_trace', {})
        bid = prev.get('bid') if prev else None
        if bid is not None:
            prev_bids.append(float(bid))

    if prev_bids:
        highest_prev = max(prev_bids)
        avg_prev = sum(prev_bids) / len(prev_bids)
    else:
        highest_prev = 140.0
        avg_prev = 135.0

    units_available = int(supply // WATER_REQ)
    tight_supply = units_available <= 1
    abundant_supply = units_available >= 2

    danger = 0
    if hp <= 2:
        danger += 3
    elif hp <= 4:
        danger += 2
    elif hp <= 6:
        danger += 1

    if no_water >= 2:
        danger += 3
    elif no_water >= 1:
        danger += 2

    if tight_supply:
        danger += 2
    elif abundant_supply:
        danger -= 1

    danger += min(2, urgent_opp_count)

    if budget < 70:
        cap = budget
    elif budget < 140:
        cap = min(budget, highest_prev + 3.0)
    else:
        cap = min(budget, highest_prev + 8.0)

    if danger <= 0:
        bid = 18.0 if abundant_supply else 28.0
    elif danger == 1:
        bid = max(32.0, avg_prev * 0.28)
    elif danger == 2:
        bid = max(48.0, avg_prev * 0.42)
    elif danger == 3:
        bid = max(72.0, avg_prev * 0.58)
    elif danger == 4:
        bid = max(96.0, highest_prev * 0.72)
    else:
        bid = max(118.0, highest_prev + 2.0)

    if tight_supply and rich_opp_count >= 2:
        bid = max(bid, highest_prev * 0.88)
    if abundant_supply and hp > 4 and no_water == 0:
        bid = min(bid, avg_prev * 0.45)

    if hp <= 2 or no_water >= 2:
        bid = max(bid, highest_prev + 1.5)

    bid = min(bid, cap)
    bid = min(bid, budget)
    if bid < 0:
        bid = 0.0
    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = day_context.get('day', 0)

    hp = float(my_status.get('hp', 0.0))
    budget = float(my_status.get('budget', 0.0))
    no_water_days = int(my_status.get('no_water_days', 0))

    alive_opps = []
    for opp in opponents_status.values():
        if opp.get('alive', False):
            alive_opps.append(opp)

    if not alive_opps:
        return max(0.0, min(budget, DAILY_SALARY * 0.4))

    # Immediate reaction to yesterday's visible bids
    prev_bids = []
    prev_hp_after = []
    prev_budgets_after = []
    for opp in alive_opps:
        prev = opp.get('previous_trace', {}) or {}
        bid = prev.get('bid', None)
        if bid is not None:
            prev_bids.append(float(bid))
            prev_hp_after.append(float(prev.get('hp_after', 0.0)))
            prev_budgets_after.append(float(prev.get('budget_after', 0.0)))

    if not prev_bids:
        # No signal; bid based on our pressure
        pressure = 0.0
        if no_water_days > 0:
            pressure += 0.35
        if hp <= 2:
            pressure += 0.6
        target = DAILY_SALARY * (0.45 + pressure)
        return max(0.0, min(budget, target))

    highest_prev_bid = max(prev_bids)
    avg_prev_bid = sum(prev_bids) / float(len(prev_bids))

    # Identify who likely over/underbid: dying quickly with low bid implies others can clear cheaply.
    # We use the pattern: if many opponents had low bids and still survived, bid lower.
    low_bid_ratio = 0.0
    cnt_low = 0
    for b in prev_bids:
        if b <= DAILY_SALARY * 0.7:
            cnt_low += 1
    low_bid_ratio = cnt_low / float(len(prev_bids))

    # Supply affects how many units are available; with higher supply, we can bid less.
    supply_norm = 0.0
    if MAX_SUPPLY > MIN_SUPPLY:
        supply_norm = (supply - MIN_SUPPLY) / float(MAX_SUPPLY - MIN_SUPPLY)
    # supply_norm in [0,1] ideally
    if supply_norm < 0.0:
        supply_norm = 0.0
    if supply_norm > 1.0:
        supply_norm = 1.0

    # Our pressure
    pressure = 0.0
    if no_water_days >= 1:
        pressure += 0.25
    if no_water_days >= 2:
        pressure += 0.25
    if hp <= 2:
        pressure += 0.6
    elif hp <= 4:
        pressure += 0.25

    # Strategy:
    # - If yesterday's highest bid was very high, assume a bidding war; bid to clear but cap spending.
    # - If low bids were common, we can undercut.
    war_signal = 0.0
    if highest_prev_bid >= DAILY_SALARY * 0.85:
        war_signal = 1.0
    elif highest_prev_bid >= DAILY_SALARY * 0.65:
        war_signal = 0.6

    # Base bid around a fraction of highest/average
    if war_signal >= 0.9:
        target = min(highest_prev_bid * 0.85 + 2.0, DAILY_SALARY * 0.95)
    elif war_signal >= 0.6:
        target = min(max(avg_prev_bid * 0.85, DAILY_SALARY * 0.6), DAILY_SALARY * 0.85)
    else:
        # Undercut if low bids were common
        if low_bid_ratio >= 0.5:
            target = max(DAILY_SALARY * 0.45, avg_prev_bid * 0.7)
        else:
            target = max(DAILY_SALARY * 0.55, avg_prev_bid * 0.8)

    # Adjust for our pressure and supply
    target *= (1.0 + pressure)
    target *= (1.0 - 0.2 * supply_norm)  # bid slightly less when supply is higher

    # Hard caps to avoid going broke like David did
    # If our budget is low, spend enough to survive this day but don't exceed 95% of budget.
    if budget <= 0.0:
        return 0.0

    max_spend = budget * 0.95
    # Also avoid extreme bids beyond a practical cap relative to supply
    practical_cap = DAILY_SALARY * (0.9 if war_signal > 0.5 else 0.75)
    max_spend = min(max_spend, practical_cap)

    bid = max(0.0, min(target, max_spend))

    # If we are extremely pressured, ensure we bid at least a floor
    if pressure >= 0.6:
        floor = DAILY_SALARY * 0.75
        bid = max(bid, min(budget * 0.95, floor))

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
